package org.apache.commons.math3.dfp;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math3.FieldElement;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class Dfp_multiply_TriageGen1Test {

    private Dfp fieldDfp;

    @Before
    public void setUp() {
        // Using newInstance() to get a Dfp instance from the field
        fieldDfp = new Dfp(1.0);
    }

    @Test
    public void testMultiply_PositiveInteger() {
        Dfp base = fieldDfp.newInstance(5);
        Dfp result = base.multiply(3);
        // 5 * 3 = 15
        assertEquals(new Dfp(15.0), result);
    }

    @Test
    public void testMultiply_NegativeInteger() {
        Dfp base = fieldDfp.newInstance(-4);
        Dfp result = base.multiply(2);
        // -4 * 2 = -8
        assertEquals(new Dfp(-8.0), result);
    }

    @Test
    public void testMultiply_MultiplyByZero() {
        Dfp base = fieldDfp.newInstance(123);
        Dfp result = base.multiply(0);
        // 123 * 0 = 0
        assertTrue(result.isZero());
        assertEquals(0, result.intValue());
    }

    @Test
    public void testMultiply_BaseIsZero() {
        Dfp base = fieldDfp.getZero();
        Dfp result = base.multiply(10);
        // 0 * 10 = 0
        assertTrue(result.isZero());
    }

    @Test
    public void testMultiply_One() {
        Dfp base = fieldDfp.newInstance(42);
        Dfp result = base.multiply(1);
        // 42 * 1 = 42
        assertEquals(new Dfp(42.0), result);
    }

    @Test
    public void testMultiply_NegativeResult() {
        Dfp base = fieldDfp.newInstance(5);
        Dfp result = base.multiply(-2);
        // 5 * -2 = -10
        assertEquals(new Dfp(-10.0), result);
    }

    @Test
    public void testMultiply_BothNegative() {
        Dfp base = fieldDfp.newInstance(-5);
        Dfp result = base.multiply(-3);
        // -5 * -3 = 15
        assertEquals(new Dfp(15.0), result);
    }

    @Test
    public void testMultiply_LargeInteger() {
        // Testing boundary/large integer logic if applicable
        Dfp base = fieldDfp.newInstance(1000000);
        Dfp result = base.multiply(1000);
        assertEquals(new Dfp(1000000000.0), result);
    }

    @Test
    public void testMultiply_IdentityWithOne() {
        Dfp base = fieldDfp.getOne();
        Dfp result = base.multiply(1);
        assertEquals(fieldDfp.getOne(), result);
    }
}
